document.addEventListener("DOMContentLoaded",function(){const tabs=document.querySelectorAll(".settings-tab"),sections=document.querySelectorAll(".settings-section");tabs.forEach(tab=>{tab.addEventListener("click",function(){const targetTab=this.getAttribute("data-tab");tabs.forEach(t=>t.classList.remove("active")),sections.forEach(s=>s.classList.remove("active")),this.classList.add("active"),document.getElementById(targetTab+"-section").classList.add("active")})});const newPassword=document.getElementById("new_password"),confirmPassword=document.getElementById("confirm_password");function validatePassword(){newPassword.value!==confirmPassword.value?confirmPassword.setCustomValidity("Passwords do not match"):confirmPassword.setCustomValidity("")}newPassword&&confirmPassword&&(newPassword.addEventListener("change",validatePassword),confirmPassword.addEventListener("keyup",validatePassword))});function openDeleteModal(){document.getElementById("deleteModal").style.display="block",document.body.style.overflow="hidden"}function closeDeleteModal(){document.getElementById("deleteModal").style.display="none",document.body.style.overflow="auto",document.getElementById("delete_password").value=""}window.addEventListener("click",function(event){const modal=document.getElementById("deleteModal");event.target===modal&&closeDeleteModal()}),document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".message").forEach(message=>{setTimeout(()=>{message.style.opacity="0",message.style.transform="translateY(-10px)",setTimeout(()=>{message.remove()},300)},5e3)})});
